# Read an .rds file once at startup; NULL when it is missing or unreadable,
# so that the app starts without the data generated by data-raw/.
load_rds_or_null <- function(path) {
  if (!file.exists(path)) {
    return(NULL)
  }
  tryCatch(
    readRDS(path),
    error = function(e) {
      warning("Cannot read ", path, ": ", conditionMessage(e), call. = FALSE)
      NULL
    }
  )
}
